# Let's build a mapping of group_id to first_name -> email
group_name_to_email = {}
for gid, members in group_members.items():
    mapping = {}
    for m in members:
        first = m['name'].split()[0]
        mapping[first] = m['email']
    group_name_to_email[gid] = mapping

# Let's test parsing on Edinburgh and print the mapping
print("Group 274 mapping:", group_name_to_email[274])
print("Edinburgh expenses parsed:", edinburgh_expenses)

