steps.code:
# Let's build a mapping from group_id to first_name -> email for all trip groups
group_email_maps = {}
for group in all_groups:
    gid = group['group_id']
    mapping = {}
    for member in group['members']:
        name = member['name']
        # Use first name (split by space and take first)
        first = name.split()[0]
        mapping[first] = member['email']
    group_email_maps[gid] = mapping

# Print a sample to verify
print(group_email_maps[274])

